from collections import defaultdict
G=defaultdict(list)
for r in load_lab():
 if r['family']=='xor_classification' and r['model_type']=='mlp' and r['optimizer']['type']=='SGD' and not r.get('excluded') and r.get('failed_seeds',0)==0: G[r['set_id']].append(r)
for regime in ['low','high']:
 for criterion in ['same_depth_ln','res_ge_ln','plain_terminal','deep_smooth_oneLN_vs_rect']:
  pairs=[]
  for sid,rs in G.items():
   for a,b in itertools.permutations(rs,2):
    if a['optimizer']!=b['optimizer']:continue
    delta=a['optimizer']['lr']*a['budget']['training_steps']*.01/(1-a['optimizer'].get('momentum',0))
    if (delta<.03)!=(regime=='low'):continue
    if criterion=='same_depth_ln': ok=a['residual'] and not b['residual'] and a['depth']==b['depth'] and a['n_ln']==b['n_ln'] and a['n_ln']>=1
    elif criterion=='res_ge_ln':ok=a['residual'] and not b['residual'] and a['n_ln']>=b['n_ln'] and a['n_ln']>=1 and b['n_ln']>=1
    elif criterion=='plain_terminal':ok=a['residual'] and not b['residual'] and b['layer_norm'][-1] and a['n_ln']>=b['n_ln']
    else:ok=not a['residual'] and a['depth']>=4 and a['activation'] in ['silu','gelu'] and a['n_ln']==1 and a['layer_norm'][-1] and b['activation'] in ['relu','leaky_relu'] and b['n_ln']>=2
    if ok:pairs.append((sid,a['mean']<b['mean'],a['mean']/b['mean']))
  print(regime,criterion,'n',len(pairs),'hits',sum(p[1] for p in pairs),'sets',len(set(p[0] for p in pairs)),'ratio',np.median([p[2] for p in pairs]) if pairs else None)
